def backfill_payment_history(apps, schema_editor):
    Reservation = apps.get_model("parking", "Reservation")
    PaymentTransaction = apps.get_model("parking", "PaymentTransaction")
    database = schema_editor.connection.alias

    for reservation in Reservation.objects.using(database).iterator():
        if reservation.user_id is None:
            continue
        charged_amount = reservation.amount_charged or reservation.amount_paid
        if charged_amount and charged_amount > 0:
            PaymentTransaction.objects.using(database).create(
                user_id=reservation.user_id,
                reservation_id=reservation.pk,
                kind="reservation",
                amount=charged_amount,
                created_at=reservation.created_at,
            )
        if reservation.amount_refunded and reservation.amount_refunded > 0:
            PaymentTransaction.objects.using(database).create(
                user_id=reservation.user_id,
                reservation_id=reservation.pk,
                kind="refund",
                amount=reservation.amount_refunded,
                created_at=reservation.ended_at or reservation.created_at,
            )


